/**
 * Modbus RTU frames derived from the NexIoT platform's protocol helpers.
 *
 * Source (read-only reference, no code copied or executed):
 *   https://gitee.com/NexIoT/nexiot/blob/main/cn-universal-framework/
 *     cn-universal-core/src/main/java/cn/universal/core/engine/extend/ModbusFunctions.java
 * Commit checked: 22072417fb51e6baa33ec0b895dddedbfac7b55d
 *
 * The upstream functions define:
 *   read holding request  = %02X 03 %04X(addr) %04X(qty) + CRC
 *   write single request  = %02X 06 %04X(addr) %04X(value) + CRC
 *   read holding response = slave 03 byteCount (u16 BE words...) + CRC
 *   CRC16 Modbus: init 0xFFFF, poly 0xA001, low byte transmitted first
 *
 * `crc16ModbusRef` is an independent implementation of that documented
 * algorithm, used to prove the fixtures are not generated by the code under
 * test.
 */
import type { Observation } from '../../src/domain/diff.js';

export const NEIXOT_SOURCE = {
  repo: 'https://gitee.com/NexIoT/nexiot',
  path: 'cn-universal-framework/cn-universal-core/src/main/java/cn/universal/core/engine/extend/ModbusFunctions.java',
  commit: '22072417fb51e6baa33ec0b895dddedbfac7b55d',
};

export function crc16ModbusRef(bytes: Buffer): number {
  let crc = 0xffff;
  for (const byte of bytes) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = (crc & 1) !== 0 ? ((crc >>> 1) ^ 0xa001) & 0xffff : crc >>> 1;
    }
  }
  return crc & 0xffff;
}

/** Append CRC as low byte, then high byte (Modbus RTU wire order). */
export function appendModbusCrc(pdu: Buffer): Buffer {
  const crc = crc16ModbusRef(pdu);
  return Buffer.concat([pdu, Buffer.from([crc & 0xff, (crc >>> 8) & 0xff])]);
}

export function buildReadHoldingRequest(slave: number, address: number, quantity: number): Buffer {
  const pdu = Buffer.alloc(6);
  pdu.writeUInt8(slave, 0);
  pdu.writeUInt8(0x03, 1);
  pdu.writeUInt16BE(address, 2);
  pdu.writeUInt16BE(quantity, 4);
  return appendModbusCrc(pdu);
}

export function buildWriteSingle(slave: number, address: number, value: number): Buffer {
  const pdu = Buffer.alloc(6);
  pdu.writeUInt8(slave, 0);
  pdu.writeUInt8(0x06, 1);
  pdu.writeUInt16BE(address, 2);
  pdu.writeUInt16BE(value, 4);
  return appendModbusCrc(pdu);
}

export function buildReadHoldingResponse(slave: number, registers: number[]): Buffer {
  const pdu = Buffer.alloc(3 + registers.length * 2);
  pdu.writeUInt8(slave, 0);
  pdu.writeUInt8(0x03, 1);
  pdu.writeUInt8(registers.length * 2, 2);
  registers.forEach((value, index) => pdu.writeUInt16BE(value, 3 + index * 2));
  return appendModbusCrc(pdu);
}

/**
 * Modbus TCP read-holding response.
 *
 * The upstream `isModbusTcp` rule is used as the sanity check: protocol id is
 * 0x0000 and the MBAP length field equals totalBytes - 6.
 */
export function buildReadHoldingTcp(transactionId: number, unitId: number, registers: number[]): Buffer {
  const pdu = Buffer.alloc(3 + registers.length * 2);
  pdu.writeUInt8(unitId, 0);
  pdu.writeUInt8(0x03, 1);
  pdu.writeUInt8(registers.length * 2, 2);
  registers.forEach((value, index) => pdu.writeUInt16BE(value, 3 + index * 2));

  const mbap = Buffer.alloc(6);
  mbap.writeUInt16BE(transactionId, 0);
  mbap.writeUInt16BE(0x0000, 2);
  mbap.writeUInt16BE(pdu.length, 4); // unit id + PDU
  return Buffer.concat([mbap, pdu]);
}

/** Observations for a response whose single register changes per sample. */
export function singleRegisterObservations(values: number[], slave = 1): Observation[] {
  return values.map((value, index) => ({
    frameId: `m${index + 1}`,
    vars: { register: value },
    bytes: buildReadHoldingResponse(slave, [value]),
  }));
}
